const attachBalance2023=(groups:BalanceGroup[],code:string,label:string,value:number)=>{const prefix=code.slice(0,2);const target=groups.find(group=>{
  if(groups===medipostAssets){return (prefix==='21'&&group.label==='Immobilisations incorporelles')||(['22','23','24','26'].includes(prefix)&&group.label==='Immobilisations corporelles')||(prefix==='28'&&group.label==='Immobilisations financières')||(prefix==='34'&&group.label==='Stocks')||(['40','41'].includes(prefix)&&group.label==='Créances à un an au plus')||(['49','54','55','57'].includes(prefix)&&group.label==='Trésorerie, placements et régularisations');}
  return (['10','11','12','13','14','15'].includes(prefix)&&group.label==='Capitaux propres')||(prefix==='17'&&group.label==='Dettes à plus d’un an')||(['42','44','46'].includes(prefix)&&group.label==='Dettes à un an : financières et commerciales')||(['45','47','48','49'].includes(prefix)&&group.label==='Dettes fiscales, sociales et autres');
});if(target&&!target.details.some(detail=>detail.code===code))target.details.push({code,label,values:values(value,null,null)});};
